import { Locale } from '@fe-infra/keystone-locales';
import { validateNumber } from './numberUtil';
import { toFixed } from '.';
import { globalConfigStore } from '@src/shared/stores';

const LOCALE_SEPARATOR: Record<string, { grouping: string; decimal: string }> = {
  fr: {
    grouping: ' ',
    decimal: ',',
  },
};
['de', 'es', 'id', 'it', 'pt-BR'].forEach(
  (localeCode) =>
    (LOCALE_SEPARATOR[localeCode] = {
      grouping: '.',
      decimal: ',',
    }),
);

let groupingSeparator: string;
let groupingSeparatorRegexp: RegExp;
let decimalSeparator: string;
let validCharSet: Set<string>;
function resetNumberLocalizationSetting(locale: Locale) {
  // TODO prettify this type
  const newGroupingSeparator = LOCALE_SEPARATOR[locale]?.grouping || ',';
  const newDecimalSeparator = LOCALE_SEPARATOR[locale]?.decimal || '.';

  if (newGroupingSeparator === groupingSeparator && newDecimalSeparator === decimalSeparator) {
    // istanbul ignore next
    return;
  }

  groupingSeparator = newGroupingSeparator;
  decimalSeparator = newDecimalSeparator;

  validCharSet = new Set([groupingSeparator, decimalSeparator, ...'0123456789']);
  groupingSeparatorRegexp = new RegExp(`\\${groupingSeparator}`, 'g');
}

resetNumberLocalizationSetting(globalConfigStore.get('locale'));
globalConfigStore.onChange('locale', (locale) => resetNumberLocalizationSetting(locale));

export function sanitizeLocalizedNumber(localizedNumber: string) {
  let sanitized = '';
  let hasEncounteredDecimalSeparator = false;

  for (const char of localizedNumber) {
    if (!validCharSet.has(char)) {
      continue;
    }

    if (char === decimalSeparator) {
      if (hasEncounteredDecimalSeparator) {
        break;
      }
      hasEncounteredDecimalSeparator = true;
    }
    sanitized += char;
  }

  return sanitized;
}

export function parseLocalizedNumber(localizedNumber: string): string {
  return localizedNumber.replace(groupingSeparatorRegexp, '').replace(decimalSeparator, '.');
}

export function formatToLocalizedNumber(number: string, precision?: number) {
  if (validateNumber(number) && ((precision !== undefined && precision >= 0) || decimalSeparator)) {
    number = toFixed(number, decimalSeparator, precision);
  }

  const [startPart, end] = number.split('.');

  const start = `${startPart}`.replace(/\B(?=(\d{3})+(?!\d))/g, groupingSeparator);
  return `${start}${end ? `${decimalSeparator}${end}` : ''}`;
}
