import BigIntDecimal from './BigIntDecimal';
import { trimNumber, getNumberPrecision, num2str, validateNumber } from './numberUtil';

export { trimNumber, getNumberPrecision, num2str, validateNumber, BigIntDecimal };

export { formatToLocalizedNumber, parseLocalizedNumber, sanitizeLocalizedNumber } from './number';

/**
 * Align the logic of toFixed to around like 1.5 => 2.
 * If set `cutOnly`, will just remove the over decimal part.
 */
export function toFixed(numStr: string, separatorStr: string, precision?: number, cutOnly = false) {
  if (numStr === '') {
    return '';
  }
  const { negativeStr, integerStr, decimalStr } = trimNumber(numStr);
  const precisionDecimalStr = `${separatorStr}${decimalStr}`;

  const numberWithoutDecimal = `${negativeStr}${integerStr}`;

  if (precision !== undefined && precision >= 0) {
    // We will get last + 1 number to check if need advanced number
    const advancedNum = Number(decimalStr[precision]);

    if (advancedNum >= 5 && !cutOnly) {
      const advancedDecimal = new BigIntDecimal(numStr).add(
        `${negativeStr}0.${'0'.repeat(precision)}${10 - advancedNum}`,
      );
      return toFixed(advancedDecimal.toString(), separatorStr, precision, cutOnly);
    }

    if (precision === 0) {
      return numberWithoutDecimal;
    }

    return `${numberWithoutDecimal}${separatorStr}${decimalStr.padEnd(precision, '0').slice(0, precision)}`;
  }

  if (precisionDecimalStr === '.0') {
    return numberWithoutDecimal;
  }

  return `${numberWithoutDecimal}${precisionDecimalStr}`;
}
